/* Helper â€” builds an optimised Unsplash URL from a photo id.
   img(id, width, quality?, height?) â€” height pins the exact crop,
   which prevents layout shift while images stream in.
   Replace calls like img("ID", w) with your own file paths anytime. */
function img(id, w, q, h) {
  var key = "unsplash-" + id + "-" + w;
  var r2 = window.__R2_MAP && window.__R2_MAP[key];
  if (r2) return r2;
  var url = "https://images.unsplash.com/photo-" + id +
    "?q=" + (q || 78) + "&w=" + w + "&auto=format&fit=crop";
  if (h) url += "&h=" + h;
  return url;
}

